#include <QCoreApplication>
#include <QSaveFile>
#include <QTemporaryDir>
#include <QElapsedTimer>
#include <QFile>
#include <iostream>
int main(int argc,char**argv){QCoreApplication app(argc,argv);QTemporaryDir d("working/save-profile-XXXXXX");QByteArray b(960000,'x');QElapsedTimer t;t.start();for(int i=0;i<40;++i){QSaveFile f(d.filePath(QString::number(i)));if(!f.open(QIODevice::WriteOnly)||f.write(b)!=b.size()||!f.commit())return 1;}std::cout<<"qsave ms "<<t.elapsed()<<'\n';t.restart();for(int i=0;i<40;++i){const auto p=d.filePath(QString::number(i+40));QFile f(p+".tmp");if(!f.open(QIODevice::WriteOnly|QIODevice::NewOnly)||f.write(b)!=b.size())return 1;f.close();if(!QFile::rename(p+".tmp",p))return 1;}std::cout<<"close/rename ms "<<t.elapsed()<<'\n';}
